INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end, capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source, confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Kemet (Old Kingdom)', 'egy-Latn', NULL, NULL, 'AtlasPI period-state display form under the Kemet civilization umbrella (ETHICS-015 decomposition). Flag: km.t is not attested as a country name in Old Kingdom sources — earliest secure attestation is late First Intermediate Period / Middle Kingdom.', 'Wikipedia: Km and Km.t (Kemet) (hieroglyphs); Gardiner, Ancient Egyptian Onomastica');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'km.t (𓆎𓅓𓏏𓊖, Kemet, "the Black Land")', 'egy', -2100, NULL, 'Native name of Egypt used retrospectively; attested as a country designation only from c. -2100 onward, NOT in Old Kingdom texts. Refers to the black Nile alluvium as opposed to dšrt, the "red land" desert.', 'Wikipedia: Km and Km.t (Kemet) (hieroglyphs)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'tꜣ.wy (Tawy, "the Two Lands")', 'egy', -2686, -2160, 'Attested in-period designation of the unified state (Upper + Lower Egypt) in the Pyramid Texts and royal titulary (nb tꜣ.wy, zmꜣ-tꜣ.wy unification motif). Transliteration and vocalization are modern Egyptological conventions.', 'Pyramid Texts; Wikipedia: Upper and Lower Egypt');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Old Kingdom of Egypt', 'en', NULL, NULL, 'Modern historiographic construct; standard in Anglophone Egyptology.', 'Shaw (ed.), The Oxford History of Ancient Egypt, 2000');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Altes Reich', 'de', NULL, NULL, 'Original 19th-century historiographic coinage (German Egyptology), from which the English term derives.', 'Wikidata Q177819 German label');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'المملكة المصرية القديمة', 'ar', NULL, NULL, 'Modern Arabic historiography, including Egyptian national scholarship (Ministry of Tourism and Antiquities).', 'Wikidata Q177819 Arabic label; egymonuments.gov.eg');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), -2686, 'Nile Valley and Delta (Memphite state)', 'INHERITANCE', 'Start of Dynasty 3 (Netjerikhet/Djoser) per Shaw chronology — a historiographic period boundary, not a territorial acquisition: the Old Kingdom monarchy continued the already-unified Early Dynastic state (Dynasties 1-2). Hornung/Krauss/Warburton 2006 place this c. -2592, up to ~95 years later.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), -2600, 'Lower Nubia (Ta-Sety, south of the First Cataract)', 'CONQUEST_MILITARY', 'King Sneferu''s razzia into Nubia, recorded in the Palermo Stone royal annals: 7,000 Nubians carried off as captives and 200,000 head of livestock seized. Archaeology shows Lower Nubia (A-Group culture) largely depopulated afterwards. A raid and forced mass deportation by the Egyptian crown, not a permanent annexation; the figures are the perpetrator state''s own boast and may be rounded or inflated. No Nubian textual record exists (preliterate society).', NULL, 0.65);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), -2600, 'Tjehenu (Libyan western desert margins)', 'CONQUEST_MILITARY', 'The Palermo Stone annals also credit Sneferu with a raid against the Tjehenu (Libyans): 11,000 captives and 13,100 cattle per the common reading (the numerals are debated). Perpetrator: the Egyptian crown under Sneferu.', NULL, 0.5);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), -2300, 'Northern Sinai / southern Levant (land of the ''Sand-dwellers'')', 'CONQUEST_MILITARY', 'Under Pepi I (Dynasty 6), general Weni led five punitive campaigns against the Aamu ''Sand-dwellers''. His tomb autobiography boasts that the army razed settlements, cut down fig trees and vines, and carried off captives ''in very great numbers''. Destructive raids for security and plunder, not annexation.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), -2160, 'Entire state — fragmentation into nomarch-ruled polities (First Intermediate Period)', 'UNKNOWN', 'Collapse of centralized Memphite rule. Causes debated, deliberately NOT resolved here: (a) climate camp — the 4.2 ka BP aridification event and low Nile floods causing famine (Nile Delta sedimentation studies; Yale/Manning discussion of the drought record); (b) structural camp — long-term decentralization: growing hereditary nomarch autonomy, expansion of tax-exempt temple estates, and the destabilizing ultra-long reign of Pepi II (Bárta: a long embedded process, not a sudden catastrophe). Manning disputes a direct low-Nile causation; Moeller cautions against climate monocausality. Date convention: Shaw ends Dynasty 6 at -2181 and the Memphite Dynasties 7/8 c. -2160 (used here); HKW end c. -2150/-2118.', NULL, 0.5);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Shaw, Ian (ed.), The Oxford History of Ancient Egypt, Oxford University Press, 2000 — esp. Jaromír Málek, ''The Old Kingdom (c. 2686-2160 BC)''. Chronological framework used for year_start/year_end.', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Hornung, Erik; Krauss, Rolf; Warburton, David A. (eds.), Ancient Egyptian Chronology, Handbook of Oriental Studies I/83, Brill, Leiden, 2006 — chronological tables pp. 490-495 (Dynasty 3 from c. 2592, end of Old Kingdom c. 2150/2118 BCE).', 'https://brill.com/edcollbook/title/7028', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Wilkinson, Toby A. H., Royal Annals of Ancient Egypt: The Palermo Stone and its Associated Fragments, Kegan Paul International, London, 2000 — edition and translation of the Palermo Stone, the primary source for Sneferu''s Nubian (7,000 captives, 200,000 cattle) and Libyan raids.', NULL, 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Lehner, Mark, ''Labor and the Pyramids: The Heit el-Ghurab "Workers Town" at Giza'', in Steinkeller & Hudson (eds.), Labor in the Ancient World, ISLET, 2015 — archaeological evidence for corvée-conscripted (not enslaved) pyramid labor.', 'https://www.researchgate.net/publication/303875906_Labor_and_the_Pyramids_The_Heit_el-Ghurab_Workers_Town_at_Giza', 'archaeological');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Hawass, Zahi & Lehner, Mark, ''Builders of the Pyramids'', Archaeology 50/1, 1997, pp. 30-38 — builders'' cemetery and workers'' settlement at Giza; Egyptian-led excavation (non-Western historiography: Hawass, Egyptian Supreme Council of Antiquities).', 'https://www.academia.edu/36645637/1997_Pyramid_Builders_Hawass_and_Lehner_pdf', 'archaeological');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 'Moeller, Nadine, ''The First Intermediate Period: A Time of Famine and Climate Change?'', Ägypten und Levante / Egypt and the Levant 15, 2005, pp. 153-167 — critique of climate monocausality for the Old Kingdom collapse.', NULL, 'academic');
INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end, capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source, confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'km.t', 'egy', NULL, NULL, 'Attested consonantal endonym, ''Black Land'' (hieroglyphic 𓆎𓅓𓏏𓊖), referring to the fertile Nile soil; attested in Middle Kingdom literature itself (e.g., Tale of Sinuhe). ''Kemet'' is the conventional modern vocalization; Coptic descendant Keme.', 'Woerterbuch der aegyptischen Sprache V, 126-127; Tale of Sinuhe (P. Berlin 3022)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'T3wy', 'egy', NULL, NULL, '''The Two Lands'' (Upper and Lower Egypt), attested self-designation of the unified state; the capital name Itj-tawy (''Seizer of the Two Lands'') derives from it.', 'Royal titulary, Middle Kingdom inscriptions');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Middle Kingdom of Egypt', 'en', -2055, -1650, 'Modern Egyptological periodization (19th-century construct, not an ancient name).', 'Shaw, I. (ed.), The Oxford History of Ancient Egypt (2000)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Mittleres Reich', 'de', NULL, NULL, 'German Egyptological term; the tripartite ''Reich'' periodization originated in 19th-century German scholarship.', 'German Egyptological literature');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Medio Regno d''Egitto', 'it', NULL, NULL, 'Modern Italian historiography.', NULL);
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'المملكة الوسطى', 'ar', NULL, NULL, 'Modern Arabic (Egyptian) historiography.', NULL);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), -2040, 'Lower and Middle Egypt (Herakleopolitan kingdom)', 'CONQUEST_MILITARY', 'Mentuhotep II of Thebes (11th Dynasty) defeated the Herakleopolitan 10th Dynasty and reunified Egypt by force, taking the title Sema-tawy (''He who unites the Two Lands''). Final victory came around his regnal year 39: c. 2040 BCE in the conventional dating, c. 2016 BCE if his accession is placed at 2055 (Shaw). The entity''s start year (-2055) follows Shaw''s accession date; the conquest itself was a process spanning his mid-reign, triggered in part by the Herakleopolitan desecration of the Abydos necropolis.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), -1938, 'Lower Nubia to the Second Cataract (Buhen)', 'CONQUEST_MILITARY', 'Senusret I''s armies (campaign of regnal year 18, led by general Mentuhotep) conquered Lower Nubia and established the fortress of Buhen at the Second Cataract, with influence reaching toward the Third Cataract. Explicit military occupation of Nubian land, opening Egyptian exploitation of Nubian gold and trade routes. Perpetrator: the Egyptian crown under Senusret I.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), -1854, 'Lower Nubia (Semna boundary and fortress chain)', 'CONQUEST_MILITARY', 'Senusret III campaigned repeatedly in Nubia (regnal years 6/8, 10, 16, 19; c. 1864-1851 BCE) and fixed Egypt''s formal boundary at the Semna gorge, completing a chain of fortresses (Semna, Kumma, Uronarti, Askut, Mirgissa, Buhen) that policed Nubian movement — Nubians could pass only for trade or official business — and monopolized commerce. His Semna boundary stela of year 16 (Berlin AeM 1157) brands the enemy ''wretched Kush'' and boasts: ''I captured their women, I carried off their underlings, went to their wells, drove off their bulls, tore out their barley, set fire to it.'' Military occupation and dehumanizing royal ideology, perpetrator named: Senusret III and the Egyptian state.', NULL, 0.7);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), -1820, 'Faiyum depression', 'UNKNOWN', 'Internal expansion, not conquest: multi-generational irrigation and land-reclamation project from Senusret II onward, peaking under Amenemhat III, converted large parts of the Faiyum into cultivable, administered land.', NULL, 0.7);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), -1700, 'Lower Nubia (fortress chain)', 'UNKNOWN', 'During the 13th Dynasty the state''s grip weakened and control of the Nubian fortresses lapsed; garrison communities remained and passed into the service of the expanding Kingdom of Kush (Kerma). From the Nubian perspective this was a recovery of occupied land by an independent African state. Gradual process, date approximate.', NULL, 0.4);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), -1650, 'Lower Egypt (Avaris, Memphis)', 'CONQUEST_MILITARY', 'The Hyksos 15th Dynasty, rulers of West Asian (Levantine) origin based at Avaris, seized control of Lower Egypt including Memphis; the Itjtawy state collapsed and the Second Intermediate Period began. The nature of the takeover is disputed — gradual Levantine settlement culminating in an internal seizure of power vs. armed invasion — the debate is recorded, not resolved. By late 13th Dynasty reigns (e.g., Merneferre Ay) royal authority had already contracted to the south.', NULL, 0.5);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Callender, G. (2000). ''The Middle Kingdom Renaissance (c. 2055-1650 BC)''. In Shaw, I. (ed.), The Oxford History of Ancient Egypt. Oxford: Oxford University Press, pp. 148-183.', 'https://archive.org/details/oxfordhistoryofa0000unse_u4p1', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Grajetzki, W. (2006). The Middle Kingdom of Ancient Egypt: History, Archaeology and Society. London: Duckworth.', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Smith, S.T. (1995). Askut in Nubia: The Economics and Ideology of Egyptian Imperialism in the Second Millennium B.C. London: Kegan Paul International.', NULL, 'archaeological');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Boundary stela of Senusret III from Semna, regnal year 16 (c. 1854 BCE), Aegyptisches Museum und Papyrussammlung, Berlin, AeM 1157.', 'https://smb.museum-digital.de/object/502', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Mokhtar, G. (ed.) (1981). General History of Africa, Vol. II: Ancient Civilizations of Africa. Paris: UNESCO / London: Heinemann.', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 'Arnold, D. (2008). Middle Kingdom Tomb Architecture at Lisht. Publications of The Metropolitan Museum of Art Egyptian Expedition, Vol. 28. New Haven: Yale University Press.', NULL, 'archaeological');
INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end, capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source, confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), '𓆎𓅓𓏏𓊖 (km.t)', 'egy', NULL, NULL, 'Attested endonym, hieroglyphic: ''the Black Land'', from the fertile black Nile silt. Attested from the Old Kingdom onward and throughout New Kingdom texts. The vocalization ''Kemet'' is a modern Egyptological convention — ancient pronunciation uncertain.', 'Wörterbuch der aegyptischen Sprache / TLA lemma km.t; New Kingdom royal inscriptions');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Kemet', 'egy-Latn', NULL, NULL, 'Modern Egyptological romanization of km.t; used as primary name per AtlasPI local-name-first policy', 'standard Egyptological usage');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'tꜣ-mrj (Ta-mery)', 'egy', NULL, NULL, '''The beloved land'' — poetic endonym attested in New Kingdom texts', 'New Kingdom literary and monumental texts');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Miṣri', 'akk', -1360, -1330, 'Akkadian exonym for Egypt in the Amarna diplomatic correspondence (EA tablets) — contemporary non-Egyptian, non-Western attestation', 'Amarna letters (EA archive, Akhetaten)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'New Kingdom of Egypt', 'en', -1550, -1069, 'Modern historiographic periodization (19th-century Egyptology); not an ancient name', 'Shaw (ed.), Oxford History of Ancient Egypt, 2000');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Egyptian Empire', 'en', -1550, -1069, 'Standard historiographic label — the only period of pharaonic Egypt conventionally called an ''empire'' (basis for entity_type)', 'Wikidata Q180568 label (verified 2026-07-04)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Nuovo Regno d''Egitto', 'it', NULL, NULL, 'Italian historiographic form', 'standard Italian Egyptological usage');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1550, 'Avaris and Lower Egypt (Nile Delta)', 'CONQUEST_MILITARY', 'Ahmose I (founder of the 18th Dynasty) sacked the Hyksos capital Avaris, expelled the 15th (Hyksos) Dynasty and pursued them into southern Canaan with a multi-year siege of Sharuhen. Egypt reunified by force under Theban rule — conventional start of the New Kingdom (Shaw chronology).', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1500, 'Nubia (Kush) to Kurgus, beyond the Fourth Cataract', 'CONQUEST_MILITARY', 'Thutmose I invaded Kush and killed its ruler; his Tombos stela boasts of Nubian corpses strewn across their valleys. He carved a boundary tableau at Hagar el-Merwa (Kurgus), upstream of the Fourth Cataract — perpetrator: the Egyptian state; victims: the Kushite kingdom of Kerma and Nubian populations.', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1457, 'Canaan and the Levant (Megiddo)', 'CONQUEST_MILITARY', 'Thutmose III defeated the Kadesh-led Canaanite coalition at Megiddo — the first battle in history recorded in reliable detail (Annals, Hall of Annals at Karnak, scribe Tjaneni). Seventeen campaigns over two decades reduced the Canaanite and Syrian city-states to tribute-paying vassals under Egyptian garrisons; thousands of captives were deported to Egypt as unfree labor.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1450, 'Upper Nubia (Napata / Gebel Barkal)', 'COLONIZATION', 'Thutmose III founded Napata below Gebel Barkal, consolidating colonial rule over Kush: a viceroy (''King''s Son of Kush''), industrial-scale gold extraction (Wadi Allaqi, Eastern Desert) with conscripted labor, and temple-towns (Sesebi, Soleb, Amara West) as instruments of administration and forced cultural Egyptianization. Explicit colonial extraction from Kush that financed the empire.', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1259, 'Syria (Kadesh / Amurru frontier)', 'TREATY', 'Egyptian–Hittite treaty between Ramesses II and Hattusili III — the earliest surviving international peace treaty (silver tablet original; hieroglyphic copies at Karnak and the Ramesseum; Akkadian tablet from Hattusa, now Istanbul Archaeology Museums; replica at UN headquarters). It stabilized the frontier after the drawn Battle of Kadesh (-1274): Kadesh and Amurru stayed Hittite, Canaan stayed Egyptian. Ramesses II''s Kadesh ''victory'' reliefs are state propaganda; the battle was a stalemate.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1177, 'Nile Delta and Djahy (coastal Levant)', 'CONQUEST_MILITARY', 'Ramesses III repelled the Sea Peoples'' combined land and sea invasions (Medinet Habu reliefs and inscriptions, regnal year 8, c. -1177). Egypt survived the eastern-Mediterranean collapse that destroyed Hatti and Ugarit, but its Levantine holdings eroded in the following decades as Philistines and others settled coastal Canaan.', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1140, 'Canaan and Syria', 'UNKNOWN', 'Gradual, poorly documented Egyptian withdrawal from the Levantine empire; the last secure attestations of Egyptian control date to Ramesses VI (c. -1141..-1133). Marked UNKNOWN because no single conquest or treaty ended it — the tribute system dissolved with Egyptian state capacity.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), -1069, 'Nubia and Upper Egypt', 'REVOLUTION', 'Internal breakdown of the 20th Dynasty under Ramesses XI: state-prosecuted royal tomb robberies (Tomb Robbery Papyri, e.g. P. Abbott), grain crises after the first recorded labor strike at Deir el-Medina (-1157, year 29 of Ramesses III), and civil war between viceroy Panehesy of Kush and the Theban high priesthood of Amun. Nubia was lost; power split between Smendes at Tanis and the high priests of Amun at Thebes — start of the Third Intermediate Period (conventional end date -1069, Shaw).', NULL, 0.7);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Ian Shaw (ed.), The Oxford History of Ancient Egypt, Oxford University Press, 2000 — New Kingdom chapters; source of the 1550–1069 BCE chronology used here', 'https://global.oup.com/academic/product/the-oxford-history-of-ancient-egypt-9780192804587', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Stuart Tyson Smith, Wretched Kush: Ethnic Identities and Boundaries in Egypt''s Nubian Empire, Routledge, 2003', 'https://books.google.com/books/about/Wretched_Kush.html?id=fsbmHwcbfFIC', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Ellen Morris, Ancient Egyptian Imperialism, Wiley-Blackwell, 2018', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Donald B. Redford, Egypt, Canaan, and Israel in Ancient Times, Princeton University Press, 1992', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Eric H. Cline, 1177 B.C.: The Year Civilization Collapsed, Princeton University Press, 2014', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Annals of Thutmose III, Hall of Annals, Temple of Amun-Re at Karnak (Urk. IV) — Megiddo campaign account by the scribe Tjaneni', 'https://en.wikipedia.org/wiki/Annals_of_Thutmose_III', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 'Egyptian–Hittite peace treaty (c. 1259 BCE), Ramesses II–Hattusili III: hieroglyphic copies at Karnak and the Ramesseum; Akkadian tablet from Hattusa, Istanbul Archaeology Museums', 'https://en.wikipedia.org/wiki/Egyptian%E2%80%93Hittite_peace_treaty', 'primary');
