INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end, capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source, confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Πτολεμαϊκὴ βασιλεία', 'grc', -305, -30, 'Koine Greek form used as the standard name in scholarship and reference works (romanized Ptolemaïkḕ basileía). HONESTY NOTE: the adjective Ptolemaïkos and the word basileia are amply attested in ancient sources, but the compound phrase as an official state name is a scholarly convention — contemporary documents named the state through its ruler (''King Ptolemy'' / hē basileia of Ptolemy).', 'Wikipedia/Wikidata Q2320005; conventional in Hölbl 2001 and Manning 2010');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Kmt (Kemet, 𓆎𓅓𓏏𓊖)', 'egy', -305, -30, 'Native Egyptian name of the land itself, still used in hieroglyphic and demotic documents of the period; the Ptolemies bore full pharaonic titularies in Egyptian (e.g. on the Rosetta Stone). There was no separate native name for the dynasty''s state.', 'Memphis decree (Rosetta Stone), 196 BCE');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Ptolemaic Kingdom', 'en', NULL, NULL, 'Standard English name', 'Wikidata Q2320005');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Ptolemaic Egypt', 'en', NULL, NULL, 'Common English alternative', 'Wikidata Q2320005 alias');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Lagid Kingdom', 'en', NULL, NULL, 'From Lagos, father of Ptolemy I; the dynasty is also called the Lagids', 'Wikidata Q2320005 alias');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Royaume lagide', 'fr', NULL, NULL, 'Standard in French historiography (e.g. Véïsse 2004)', 'Véïsse 2004');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'الدولة البطلمية', 'ar', NULL, NULL, 'Modern Arabic historiographical name (also مصر البطالمة, ''Ptolemaic Egypt'')', 'modern Arabic historiography');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -332, 'Egypt (Nile valley and Delta)', 'CONQUEST_MILITARY', 'Alexander III of Macedon conquered Egypt from the Achaemenid Persian occupation (Second Persian Period); the Persian satrap surrendered without major battle. Predates the kingdom proper but is the founding act of Macedonian rule; Alexandria founded 331 BCE.', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -323, 'Egypt', 'TREATY', 'Partition of Babylon after Alexander''s death: Ptolemy son of Lagos assigned Egypt as satrap. He ruled as satrap 323-305, seizing Alexander''s corpse (321) and defending Egypt against Perdiccas (321/320).', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -322, 'Cyrenaica', 'CONQUEST_MILITARY', 'Ptolemy I''s general Ophellas subjugated Cyrene and Cyrenaica by military force, exploiting the city''s civil strife; held (with revolts) as Ptolemaic dependency.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -301, 'Coele-Syria, Phoenicia, Judea', 'CONQUEST_MILITARY', 'After the Battle of Ipsus, Ptolemy I occupied Coele-Syria and southern Phoenicia in defiance of the coalition award to Seleucus — root of the six Syrian Wars (274-168 BCE) between Ptolemies and Seleucids.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -217, 'Coele-Syria (Raphia)', 'CONQUEST_MILITARY', 'Fourth Syrian War: Ptolemy IV defeated the Seleucid Antiochus III at Raphia, retaining Coele-Syria. Polybius links the arming of ~20,000 native Egyptian phalangites at Raphia to the rise of subsequent native revolts.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -205, 'Thebaid (Upper Egypt)', 'REVOLUTION', 'Great Theban Revolt: Upper Egypt seceded from Ptolemaic rule as a native Egyptian pharaonic state under Horwennefer (proclaimed pharaoh c. 205; unrest from 206), succeeded by Ankhwennefer (199-186). An Egyptian secessionist state, not mere banditry.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -198, 'Coele-Syria, Phoenicia, Judea', 'CONQUEST_MILITARY', 'Fifth Syrian War: Antiochus III defeated the Ptolemaic army at Panium (200 BCE) and by 198 had conquered Coele-Syria, Phoenicia and Judea from Ptolemy V — permanent loss of the Levantine province.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -196, 'Nile Delta (Lycopolis)', 'CONQUEST_MILITARY', 'Ptolemy V''s forces besieged and took rebel Lycopolis in the Delta; the captured rebel leaders were executed at the king''s Memphis coronation — the repression is recorded, as royal self-celebration, on the trilingual Memphis decree (Rosetta Stone).', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -186, 'Thebaid (Upper Egypt)', 'CONQUEST_MILITARY', 'Ptolemy V''s general Comanus defeated the native pharaoh Ankhwennefer on 27 August 186 BCE, killing his son in battle; Upper Egypt forcibly reincorporated, followed by amnesty decree and garrisoning. Per the Second Philae decree Ankhwennefer was condemned to death, then pardoned at the priests'' intercession.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -168, 'Egypt (Alexandria and Memphis)', 'TREATY', 'Sixth Syrian War: Antiochus IV invaded Egypt twice (170-168) and had himself crowned; the Roman envoy C. Popillius Laenas'' ultimatum (''Day of Eleusis'') forced Seleucid withdrawal. Egypt survived intact but henceforth as a de facto Roman protectorate.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -96, 'Cyrenaica', 'INHERITANCE', 'Ptolemy Apion died bequeathing Cyrenaica to Rome by testament; Rome formally organized it as a province in 74 BCE.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -58, 'Cyprus', 'CESSION_FORCED', 'Rome annexed Ptolemaic Cyprus under the lex Clodia; king Ptolemy of Cyprus (brother of Ptolemy XII) killed himself rather than submit; Ptolemy XII of Egypt, dependent on Roman backing, did not resist.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), -30, 'Egypt (entire kingdom)', 'CONQUEST_MILITARY', 'Octavian (the future Augustus) invaded Egypt after defeating Antony and Cleopatra VII at Actium (Sept 31 BCE); Alexandria fell 1 August 30 BCE. Antony and Cleopatra died by suicide; Octavian ordered the killing of the co-ruler Ptolemy XV Caesarion, aged seventeen. Egypt annexed as a Roman province — the violent end of the last major Hellenistic kingdom.', NULL, 0.95);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Hölbl, Günther. A History of the Ptolemaic Empire. Translated by Tina Saavedra. London: Routledge, 2001. ISBN 978-0415234894.', 'https://www.routledge.com/A-History-of-the-Ptolemaic-Empire/Holbl/p/book/9780415234894', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Manning, J. G. The Last Pharaohs: Egypt Under the Ptolemies, 305–30 BC. Princeton: Princeton University Press, 2010. ISBN 978-0691156385.', 'https://press.princeton.edu/books/paperback/9780691156385/the-last-pharaohs', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Véïsse, Anne-Emmanuelle. Les « révoltes égyptiennes »: Recherches sur les troubles intérieurs en Égypte du règne de Ptolémée III Évergète à la conquête romaine. Studia Hellenistica 41. Leuven: Peeters, 2004. ISBN 978-9042913998.', 'https://www.peeters-leuven.be/detail.php?search_key=8574', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Memphis decree of Ptolemy V (Rosetta Stone), 27 March 196 BCE, trilingual (Egyptian hieroglyphic, demotic, Greek). British Museum, EA 24 — priestly decree recording royal cult, tax remissions, and the execution of the Lycopolis rebel leaders.', 'https://www.britishmuseum.org/collection/object/Y_EA24', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Polybius, Histories, Book 5 (Battle of Raphia, 5.79-86; native unrest after Raphia, 5.107) and Book 29.27 (Day of Eleusis). 2nd century BCE.', 'https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Polybius/home.html', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES ((SELECT id FROM geo_entities WHERE name_original = 'Πτολεμαϊκὴ βασιλεία'), 'Fischer-Bovet, Christelle. Army and Society in Ptolemaic Egypt. Cambridge: Cambridge University Press, 2014. ISBN 978-1107007758.', 'https://www.cambridge.org/core/books/army-and-society-in-ptolemaic-egypt/8B70E39A9ECB4E4EA6F4E20B85F09F97', 'academic');
