-- v6.99.122 (ETHICS-022) — split Kemet. Backup pg_dump PRIMA.
-- Dual-write: JSON = batch_00 (#26 retype) + batch_39. psql -v ON_ERROR_STOP=1.
BEGIN;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM geo_entities WHERE name_original IN ('tꜣ.wy (Old Kingdom)', 'tꜣ.wy (Middle Kingdom)', 'tꜣ.wy (New Kingdom)', 'Πτολεμαϊκὴ βασιλεία')) THEN RAISE EXCEPTION 'entità Kemet già presenti'; END IF; END $$;

-- ── #26 retype empire → civilization + note ──
UPDATE geo_entities SET entity_type = 'civilization', ethical_notes = ethical_notes || ' ETHICS-022 (v6.99.122): entità RI-TIPIZZATA da empire a civilization. km.t (terra nera) nomina la TERRA/civiltà, non uno stato continuo: i 3070 anni -3100..-30 comprendono i tre Periodi Intermedi di collasso e il dominio straniero Hyksos, kushita (XXV din. -747, Kush #52), assiro, persiano (Xšāça #27) e macedone. Le fasi di statualità piena sono entità proprie (tꜣ.wy Old/Middle/New Kingdom + Πτολεμαϊκὴ βασιλεία).' WHERE id = 26 AND entity_type = 'empire';

-- ── nuove entità-periodo ──
-- old_kingdom_egypt
VALUES ('tꜣ.wy (Old Kingdom)', 'egy', 'kingdom', -2686, -2160, 'Memphis (Old Kingdom name Inbu-hedj, "White Walls"; Men-nefer is the later name derived from Pepi I''s pyramid town)', 29.8494, 31.255, '{"type": "Polygon","coordinates": [[[29.85,31.15],[31,31.45],[32.3,31.2],[32.2,30.3],[31.6,29.5],[32.9,26],[33.1,24],[32.6,23.9],[32.3,25.3],[31.3,27.2],[30.3,29.2],[29.85,31.15]]]}', 'historical_approximation', 0.75, 'confirmed', '(1) NAME HONESTY: "Old Kingdom" is a modern historiographic construct (19th-century German Egyptology, "Altes Reich"); no ancient Egyptian used it. The attested in-period self-designation of the state was tꜣ.wy, "the Two Lands" (Pyramid Texts; royal title nb tꜣ.wy "Lord of the Two Lands"). The umbrella name "Kemet" (km.t, "the Black Land") is anachronistic for this specific period: its earliest secure attestation as a name for the country dates to the late First Intermediate Period / Middle Kingdom (c. 10th-12th Dynasty), not the Old Kingdom. The transliteration tꜣ.wy and vocalization "Tawy" are modern Egyptological renderings — hieroglyphic writing recorded no vowels, and the Unicode hieroglyphs are modern typesetting of ancient signs. (2) STATE VIOLENCE, PERPETRATORS NAMED: King Sneferu (founder of Dynasty 4) conducted a razzia into Lower Nubia recorded in his own royal annals (Palermo Stone): 7,000 Nubian human beings carried off as captives and 200,000 head of livestock seized. Archaeology shows the Lower Nubian A-Group population largely disappeared from the record afterwards — a violent depopulation. The only textual record is the perpetrator state''s boast; Nubia was preliterate at this date, so no Nubian counter-narrative survives — an evidentiary asymmetry, not an absence of Nubian experience. The same annals credit Sneferu with a raid on the Tjehenu (Libyans): 11,000 captives and 13,100 cattle (reading of the numerals debated). Under Pepi I (Dynasty 6), general Weni''s autobiography boasts that five campaigns against the Aamu "Sand-dwellers" (northern Sinai/southern Levant) razed settlements, cut down fig trees and vines, and carried off captives "in very great numbers". These are recorded as raids and forced deportations, not "expeditions" or "pacification". (3) PYRAMID LABOR, STATED PRECISELY: per current Egyptology (Lehner/Hawass excavations of the Heit el-Ghurab workers'' town and the builders'' cemetery at Giza), the Giza pyramids (Khufu, Khafre, Menkaure) were built by corvée conscription — a compulsory rotational labor tax on the Egyptian population — supplemented by skilled permanent crews; workers received rations, beer, medical care, and burial. This was NOT chattel slavery (the Herodotean/Hollywood trope is rejected), but it was also not free voluntary labor: it was state compulsion. Both halves of that sentence matter. (4) DISPUTES RECORDED, NOT RESOLVED: chronology (Shaw vs Hornung/Krauss/Warburton, up to ~95 years divergence) and collapse causation (climate vs structural decentralization) are documented as open debates below.', 'Q177819', ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[29.85,31.15],[31,31.45],[32.3,31.2],[32.2,30.3],[31.6,29.5],[32.9,26],[33.1,24],[32.6,23.9],[32.3,25.3],[31.3,27.2],[30.3,29.2],[29.85,31.15]]]}')));

-- middle_kingdom_egypt
VALUES ('tꜣ.wy (Middle Kingdom)', 'egy', 'kingdom', -2055, -1650, 'Itjtawy', 29.57, 31.231, '{"type": "Polygon","coordinates": [[[30.4,31.35],[32.35,31.1],[32.6,29.5],[33.3,25.9],[32.95,24],[31.3,21.45],[30.6,21.45],[31,23.9],[30.4,26.2],[29.85,29.2],[30.2,30.5],[30.4,31.35]]]}', 'historical_approximation', 0.75, 'confirmed', 'Naming: km.t ("Black Land", hieroglyphic 𓆎𓅓𓏏𓊖) is the attested endonym, well documented in Middle Kingdom texts themselves (e.g., Tale of Sinuhe); the vocalization "Kemet" is a modern Egyptological convention (the script wrote consonants only; Coptic descendant Keme). "Middle Kingdom" is a 19th-century European periodization, not an ancient name — the parenthetical is kept transparently as a modern qualifier distinguishing this period-state under the Kemet umbrella entity, same approach as the Old Kingdom record. Violence made explicit: (1) The reunification that founded this state was military conquest — Mentuhotep II of Thebes defeated and annexed the Herakleopolitan (10th Dynasty) kingdom; slain soldiers buried near his Deir el-Bahri temple attest the wars'' human cost. (2) The 12th Dynasty conquered and militarily occupied Lower Nubia: Senusret I''s armies (campaign c. 1938 BCE, general Mentuhotep) pushed to the Second Cataract and built Buhen; Senusret III''s campaigns (c. 1864-1851 BCE) fixed the boundary at Semna and completed a fortress chain that policed Nubian movement and seized control of trade. Royal ideology dehumanized Nubians as "wretched Kush" (K3š ẖst): Senusret III''s own Semna boundary stela (Berlin ÄM 1157) boasts of capturing Nubian women, carrying off dependants, burning grain and slaughtering cattle — state violence recorded in the perpetrator''s words. Perpetrators named: the Egyptian crown under Senusret I and Senusret III. The occupied land belonged to Nubian communities and to the orbit of Kerma (Kush), an independent African state that later recovered the fortress zone. Disputes recorded, not resolved: start date (Shaw 2055 = Mentuhotep II''s accession; final reunification c. 2040 conventional, later under other chronologies; Wikidata uses 2040-1782); end date (1782/1700/1650 depending on whether the 13th Dynasty is included — Shaw''s 1650 used here); the Hyksos rise is debated between gradual Levantine settlement with internal takeover vs. invasion; Itjtawy''s exact location is unidentified.', 'Q191324', ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[30.4,31.35],[32.35,31.1],[32.6,29.5],[33.3,25.9],[32.95,24],[31.3,21.45],[30.6,21.45],[31,23.9],[30.4,26.2],[29.85,29.2],[30.2,30.5],[30.4,31.35]]]}')));

-- new_kingdom_egypt
VALUES ('tꜣ.wy (New Kingdom)', 'egy', 'empire', -1550, -1069, 'Waset (Thebes)', 25.7188, 32.6573, '{"type": "Polygon","coordinates": [[[29.8,31.45],[29.3,30.2],[28.5,28.3],[28.2,25.4],[30,22.5],[30.6,19.6],[31.6,18.2],[33.7,19.3],[33.6,22.2],[33.9,26],[32.9,29.4],[32.4,31.25],[29.8,31.45]]]}', 'historical_approximation', 0.78, 'confirmed', 'This record uses explicit language about conquest and colonial extraction, per project values. (1) NUBIA: Egypt under the 18th–20th Dynasties conquered and colonized Kush. Thutmose I''s army killed the Kushite ruler and his Tombos stela (c. -1500) boasts of Nubian corpses strewn across their valleys — royal violence celebrated as propaganda. Egypt annexed Nubia to beyond the Fourth Cataract, governed it through a viceroy (''King''s Son of Kush''), extracted gold at industrial scale from Wadi Allaqi and the Eastern Desert using conscripted labor (gold that financed the empire and its diplomacy — ''gold is like dust in your land'', Amarna letters), and planted temple-towns (Sesebi, Soleb, Amara West, Napata) as instruments of colonial administration and cultural Egyptianization. Official Egyptian rhetoric was openly contemptuous: ''Kush the wretched'' (kš ẖst) was the standard state epithet — racist framing by the perpetrator state, documented here, not endorsed. The conquered Nubians left no written counter-narrative (no indigenous script in this period); their perspective is recovered archaeologically (Tombos and Amara West excavations show cultural entanglement, resistance and biological continuity, not the total assimilation Egyptian sources claim). (2) LEVANT: Thutmose III''s 17 campaigns (from Megiddo, -1457) reduced Canaanite and Syrian city-states to tribute-paying vassals; the Annals at Karnak record thousands of captives deported to Egyptian temple estates as unfree labor. (3) PROPAGANDA VS FACT: Ramesses II''s Kadesh reliefs claim a great victory; modern consensus is a stalemate — both versions recorded, dispute documented not resolved. (4) INTERNAL VIOLENCE: Akhenaten''s regime persecuted the Amun cult and erased its names; his successors (Horemheb onward) in turn erased Akhenaten''s memory — two-way state iconoclasm. (5) NAMING: ''Kemet'' is the modern Egyptological vocalization of the attested endonym km.t (hieroglyphic 𓆎𓅓𓏏𓊖, ''the Black Land'', for the fertile Nile silt); actual ancient pronunciation is uncertain. ''New Kingdom'' and ''Egyptian Empire'' are modern historiographic labels — Egyptians did not periodize their own history this way.', 'Q180568', ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[29.8,31.45],[29.3,30.2],[28.5,28.3],[28.2,25.4],[30,22.5],[30.6,19.6],[31.6,18.2],[33.7,19.3],[33.6,22.2],[33.9,26],[32.9,29.4],[32.4,31.25],[29.8,31.45]]]}')));

-- ptolemaic_kingdom
VALUES ('Πτολεμαϊκὴ βασιλεία', 'grc', 'kingdom', -305, -30, 'Alexandria (Ἀλεξάνδρεια)', 31.2001, 29.9187, '{"type": "Polygon","coordinates": [[[25.15,31.4],[29.92,31.3],[32.55,31.1],[33.8,31.1],[32.6,29.7],[34.3,27.2],[35.55,23.9],[32.9,23.8],[30.6,24.5],[28.9,25.4],[25.4,29.2],[25.15,31.4]]]}', 'historical_approximation', 0.9, 'confirmed', 'The Ptolemaic Kingdom was a Macedonian-Greek conquest state: a Greek-speaking dynasty and settler-soldier elite ruled the native Egyptian majority following the military conquest of Egypt in 332 BCE by Alexander III of Macedon (taken from the Achaemenid Persian occupation). Greeks and Hellenized immigrants were legally and fiscally privileged over Egyptians — ''Hellene'' tax status, separate Greek courts, land allotments to Greek cleruch soldiers — and Alexandria was constitutionally a Greek polis. Native resistance was repeated and violently suppressed: in the Great Theban Revolt (unrest from c. 206, secession from 205 BCE) Upper Egypt broke away as an Egyptian pharaonic state under the native pharaohs Horwennefer (r. 205–199) and Ankhwennefer (r. 199–186); Ptolemy V''s general Comanus crushed it on 27 August 186 BCE, killing Ankhwennefer''s son in battle. Ptolemy V had the captured Delta rebel leaders of Lycopolis executed at his Memphis coronation in 196 BCE — an execution the regime itself commemorated on the Rosetta Stone; per the Second Philae decree Ankhwennefer was condemned to death and then pardoned at the priests'' intercession. The perpetrators of these repressions were the Ptolemaic kings and their armies. At the same time the dynasty presented itself as legitimate pharaohs, funded Egyptian temples, and governed through an increasingly bilingual Greek-demotic administration (trilingual Memphis decree/Rosetta Stone, 196 BCE) — domination and accommodation coexisted, and the scholarly dispute over how ''colonial'' or ''entangled'' Ptolemaic rule was (older segregationist readings vs. Manning''s and Fischer-Bovet''s integration readings) is recorded here, not resolved. The kingdom ended in violence: Octavian (Augustus) defeated Antony and Cleopatra VII at Actium (31 BCE), invaded Egypt, and took Alexandria on 1 August 30 BCE; Antony and Cleopatra died by suicide, and Octavian ordered the killing of the seventeen-year-old co-ruler Ptolemy XV Caesarion. Egypt was annexed as the personal province of the Roman emperor — the violent extinction of the last major Hellenistic kingdom. Hostile Roman portrayals of Cleopatra VII reflect Augustan propaganda and are treated critically. The record deliberately names the Egyptian secessionist state and its pharaohs rather than treating the revolt as mere ''unrest''.', 'Q2320005', ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[25.15,31.4],[29.92,31.3],[32.55,31.1],[33.8,31.1],[32.6,29.7],[34.3,27.2],[35.55,23.9],[32.9,23.8],[30.6,24.5],[28.9,25.4],[25.4,29.2],[25.15,31.4]]]}')));

