-- ── catena 3 Regni ──
VALUES ('Egyptian pharaonic kingdoms: tꜣ.wy (Old) → (Middle) → (New)', 'en', 'SUCCESSION', 'Northeast Africa / Nile Valley (Egypt)', 'The three ''Kingdom'' high-points of pharaonic Egyptian statehood (Old, Middle, New), each separated from the next by an Intermediate Period of real state collapse and (for the New Kingdom''s founding) by foreign Hyksos rule.', 0.8, 'confirmed', 'This chain links only the three periods of FULL pharaonic statehood and does NOT assert continuous statehood: it is punctuated by the First Intermediate Period (c. -2160..-2055, rival Herakleopolitan and Theban dynasties) and the Second Intermediate Period (c. -1650..-1550), during which the Levantine Hyksos (15th Dynasty) ruled Lower Egypt as a FOREIGN power. The links are typed RESTORATION precisely to mark these interruptions. The Ptolemaic Kingdom (a Macedonian-Greek state) is deliberately NOT in this chain: ~750 years of Third Intermediate Period, Late Period and foreign rule (Kushite 25th Dynasty — see Kush #52; Assyrian, Achaemenid Persian — see Xšāça #27; then Argead Macedonian) separate it from the New Kingdom. The ''Kemet'' entity #26 is the civilisation umbrella over all of this, not a continuous state.', '[{"citation": "Ian Shaw (ed.), The Oxford History of Ancient Egypt, Oxford University Press, 2000", "url": null, "source_type": "academic"}, {"citation": "Erik Hornung, Rolf Krauss, David Warburton (eds.), Ancient Egyptian Chronology, Brill (HdO 83), 2006", "url": null, "source_type": "academic"}]');
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Egyptian pharaonic kingdoms: tꜣ.wy (Old) → (Middle) → (New)'), (SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Old Kingdom)'), 0, NULL, NULL, false, 'The Old Kingdom (c. -2686..-2160), the ''pyramid age'' of the 3rd-6th Dynasties, ruled from Memphis (Inbu-hedj).', NULL);
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Egyptian pharaonic kingdoms: tꜣ.wy (Old) → (Middle) → (New)'), (SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (Middle Kingdom)'), 1, -2055, 'RESTORATION', true, 'Mentuhotep II reunified Egypt by war (c. -2055), ending the First Intermediate Period, and founded the Middle Kingdom (11th-13th Dynasties).', 'The FIRST INTERMEDIATE PERIOD (c. -2160..-2055) — real state collapse with rival Herakleopolitan and Theban dynasties — intervened between the Old and Middle Kingdoms. RESTORATION marks that interruption; the reunification itself was a military conquest.');
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Egyptian pharaonic kingdoms: tꜣ.wy (Old) → (Middle) → (New)'), (SELECT id FROM geo_entities WHERE name_original = 'tꜣ.wy (New Kingdom)'), 2, -1550, 'RESTORATION', true, 'Ahmose I expelled the Hyksos and founded the New Kingdom (18th-20th Dynasties, c. -1550..-1069), the era of the Egyptian Empire in Nubia and the Levant.', 'The SECOND INTERMEDIATE PERIOD (c. -1650..-1550), during which the Levantine Hyksos (15th Dynasty) ruled Lower Egypt as a FOREIGN power, intervened between the Middle and New Kingdoms. RESTORATION marks that interruption; Ahmose''s expulsion of the Hyksos was a war of conquest.');

-- ── validazione ──
DO $$
DECLARE n int; bad int;
BEGIN
  SELECT count(*) INTO n FROM geo_entities WHERE name_original IN ('tꜣ.wy (Old Kingdom)', 'tꜣ.wy (Middle Kingdom)', 'tꜣ.wy (New Kingdom)', 'Πτολεμαϊκὴ βασιλεία');
  IF n <> 4 THEN RAISE EXCEPTION 'attese 4 entità-periodo, trovate %', n; END IF;
  SELECT count(*) INTO n FROM geo_entities WHERE id = 26 AND entity_type = 'civilization';
  IF n <> 1 THEN RAISE EXCEPTION '#26 non ri-tipizzata'; END IF;
  SELECT count(*) INTO bad FROM event_entity_links WHERE id IN (567,18,568,424,426,582,575,577,581,22,427,20) AND entity_id = 26;
  IF bad <> 0 THEN RAISE EXCEPTION '% eventi non ri-homati', bad; END IF;
  SELECT count(*) INTO n FROM event_entity_links WHERE event_id = 39 AND entity_id = 52;
  IF n <> 1 THEN RAISE EXCEPTION 'link Kush mancante'; END IF;
  SELECT count(*) INTO n FROM event_entity_links WHERE event_id = 217 AND entity_id = 27;
  IF n <> 1 THEN RAISE EXCEPTION 'link Xšāça mancante'; END IF;
  SELECT count(*) INTO bad FROM geo_entities WHERE name_original IN ('tꜣ.wy (Old Kingdom)', 'tꜣ.wy (Middle Kingdom)', 'tꜣ.wy (New Kingdom)', 'Πτολεμαϊκὴ βασιλεία') AND (ST_XMax(boundary_geom) - ST_XMin(boundary_geom)) >= 180;
  IF bad <> 0 THEN RAISE EXCEPTION '% boundary attraversano antimeridiano', bad; END IF;
  RAISE NOTICE 'ETHICS-022 OK: #26 civilization, 4 entità-periodo, 12 eventi re-homed + 2 conquistatori, catena 3 Regni';
END $$;

COMMIT;
